"""Early grades: concrete actors, contextual ellipsis and sentence endings."""
def author(E,C,O,A,D):
 E('plan-G1-language-08','S2','공을 굴린 사람',
 '민우가 노란 공을 굴렸어요.\n하린이는 굴러온 공을 두 손으로 받았어요.\n강아지는 공 옆에 앉았어요.',
 '이 장면의 실제 행동을 연결한다. 이·가가 붙으면 언제나 행동하는 사람이라는 일반 규칙으로 확장하지 않는다.',[
 A('explanation','민우와 하린이가 한 일을 각각 써 보세요.','민우는 공을 굴렸고 하린이는 공을 받았다.',['민우가 노란 공을','하린이는 굴러온 공을'],[D('대상 구별','민우와 하린이를 구별한다.','한 사람만 구별한다.','두 사람을 모두 강아지라고 한다.'),D('행동 연결','민우의 굴리기와 하린이의 받기를 각각 잇는다.','한 행동만 바르게 잇는다.','두 행동을 서로 바꾼다.')]),
 C('공을 받은 사람은 누구인가요?','하린이','하린이가 굴러온 공을 받았다고 적혀 있다.',[('민우','민우는 공을 굴렸다.'),('강아지','강아지는 옆에 앉았다.')],'두 손으로 받았어요.'),
 O('matching','굴리기 / 앉기를 각각 누가 했는지 이으세요.','굴리기:민우 / 앉기:강아지',['노란 공을 굴렸어요.','공 옆에 앉았어요.'],'한 가지만 맞게 이음','민우가 앉았다고만 씀'),
 O('evidence_selection','하린이의 행동이 나온 문장을 찾아 쓰세요.','하린이는 굴러온 공을 두 손으로 받았어요.','굴러온 공을 두 손으로','행동만 쓰고 누가 했는지 빠뜨림','강아지가 앉은 문장을 고름')])
 E('plan-G1-language-08','S3','씨앗을 옮긴 두 손',
 '수아는 작은 그릇을 들었어요.\n도윤이는 씨앗을 수아의 그릇에 넣었어요.\n수아가 그릇을 창가로 옮겼어요.\n도윤이는 빈 봉투를 접었어요.',
 '들기·넣기·옮기기에서 행동 주체와 물건을 따로 연결한다. 그릇을 든 사람과 씨앗을 넣은 사람을 같다고 추정하지 않는다.',[
 A('explanation','씨앗을 넣은 사람과 그릇을 옮긴 사람은 누구인가요? 두 일을 이어 설명하세요.','도윤이가 씨앗을 넣고 수아가 그릇을 창가로 옮겼다.',['씨앗을 수아의 그릇에','그릇을 창가로'],[D('두 대상','씨앗 넣기는 도윤이, 옮기기는 수아라고 구별한다.','한 대상만 맞힌다.','두 대상을 서로 바꾼다.'),D('행동 관계','씨앗이 담긴 그릇을 이어 옮긴 흐름을 표현한다.','누가 했는지만 나열하고 일이 빠진다.','수아가 빈 봉투를 옮겼다고 한다.')]),
 C('수아가 창가로 옮긴 것은 무엇인가요?','그릇','창가로 옮긴 물건이 그릇이라고 적혀 있다.',[('빈 봉투','도윤이가 접은 물건이다.'),('작은 의자','이 글에 옮겼다는 내용이 없다.')],'그릇을 창가로 옮겼어요.'),
 O('ordering','그릇 들기 / 씨앗 넣기 / 창가로 옮기기를 글의 차례대로 쓰세요.','수아가 그릇 들기 → 도윤이가 씨앗 넣기 → 수아가 창가로 옮기기',['작은 그릇을 들었어요.','씨앗을 수아의 그릇에 넣었어요.'],'두 일만 잇거나 주체 하나를 빠뜨림','창가로 옮긴 뒤 씨앗을 넣었다고 함'),
 O('explanation','수아의 그릇이라는 말만 보고 씨앗도 수아가 넣었다고 할 수 있나요?','아니다. 그릇은 수아의 것이지만 씨앗을 넣은 사람은 도윤이라고 따로 적혀 있다.','도윤이는 씨앗을','아니라고만 하고 넣은 사람을 밝히지 못함','물건 주인이 모든 행동도 했다고 함')])
 E('plan-G1-language-08','S4','이어지는 한 사람의 일',
 '유진이가 종이배를 만들었어요.\n배의 한쪽을 파랗게 칠했어요.\n그때 아빠가 방에 들어왔어요.\n아빠는 종이배를 창가에 놓았어요.',
 '앞의 유진이를 이어 두 번째 행동의 주체를 찾는다. 생략은 자연스러울 수 있으며 뒤에 나온 아빠를 앞 행동에 자동으로 대입하지 않는다.',[
 A('explanation','배의 한쪽을 칠한 사람은 누구로 읽을 수 있나요? 앞뒤 말을 보고 설명하세요.','앞 문장의 유진이가 이어서 칠한 것으로 읽을 수 있다. 아빠는 그 뒤에 방에 들어왔다.',['유진이가 종이배를','그때 아빠가 방에'],[D('생략 대상 복원','칠한 사람을 앞 문장의 유진이로 읽는다.','유진이를 고르지만 행동을 설명하지 못한다.','아빠가 처음부터 칠했다고 한다.'),D('문맥 연결','앞의 만들기와 뒤의 아빠 등장을 구별해 설명한다.','문맥 한 부분만 짚는다.','글에 없는 동생을 근거로 한다.')]),
 C('글에 아빠가 했다고 분명히 적힌 일은 무엇인가요?','배를 창가에 놓기','마지막 문장이 아빠와 놓기를 연결한다.',[('종이배를 처음 만들기','유진이가 했다고 적혀 있다.'),('배의 한쪽에 색칠하기','아빠가 들어오기 전 이어진 유진이의 일로 읽힌다.')],'아빠는 종이배를 창가에'),
 O('explanation','두 번째 문장 앞에 사람 이름을 넣어 뜻을 분명히 써 보세요.','유진이가 배의 한쪽을 파랗게 칠했어요.','파랗게 칠했어요.','이름만 쓰고 문장에 넣지 못함','아빠로 바꾸어 앞뒤 뜻이 달라짐'),
 O('explanation','두 번째 문장에 이름이 없으면 언제나 틀린 문장일까요? 이 글에서 말해 보세요.','언제나 틀린 것은 아니다. 이 글에서는 앞의 유진이가 한 일을 이어 말한 것으로 알 수 있다.','유진이가 종이배를 만들었어요.','아니라고만 하고 이어지는 대상을 설명하지 못함','모든 문장에는 반드시 이름을 반복해야 한다고 함')])
 E('plan-G1-language-08','S5','장면과 다른 메모',
 '장면 기록: 나리가 인형을 준서에게 건넸어요.\n준서는 받은 인형을 작은 의자에 앉혔어요.\n친구의 메모: 준서가 나리에게 인형을 건넸어요.',
 '자연스러운 문장이더라도 장면과 다른 내용일 수 있다. 주는 사람·받는 사람을 바꾼 메모를 원래 기록에 맞춰 고친다.',[
 A('explanation','친구의 메모를 장면에 맞게 고치고 무엇을 바꾸었는지 쓰세요.','나리가 준서에게 인형을 건넸어요. 건넨 사람을 나리로, 받은 사람을 준서로 고쳤다.',['나리가 인형을 준서에게','준서가 나리에게'],[D('뜻 보존 수정','나리가 주고 준서가 받았다는 문장으로 고친다.','한 사람만 바꾸어 관계가 불분명하다.','준서가 주었다는 뜻을 유지한다.'),D('수정 이유','건넨 사람과 받은 사람의 관계가 뒤바뀌었음을 설명한다.','이름이 다르다고만 한다.','인형 색이 틀렸다고 한다.')]),
 C('인형을 작은 의자에 앉힌 사람은 누구인가요?','준서','준서는 받은 인형을 의자에 앉혔다.',[('나리','인형을 건넨 사람이다.'),('메모를 쓴 친구','그 친구가 인형을 앉혔다는 기록은 없다.')],'준서는 받은 인형을'),
 O('matching','건넨 사람 / 받은 사람을 각각 써 보세요.','건넨 사람:나리 / 받은 사람:준서','나리가 인형을 준서에게 건넸어요.','한 역할만 맞게 씀','두 역할을 바꿈'),
 O('explanation','잘못된 메모도 말 자체는 읽을 수 있어요. 그래도 고쳐야 하는 까닭은 무엇인가요?','장면에서 누가 누구에게 주었는지와 다른 내용이기 때문이다.','친구의 메모: 준서가','틀렸다고만 하고 장면과의 차이가 없음','문장은 짧으면 모두 맞다고 함'),
 O('explanation','나리와 준서가 한 일을 차례대로 두 문장으로 써 보세요.','나리가 준서에게 인형을 건넸어요. 준서가 인형을 작은 의자에 앉혔어요.',['나리가 인형을 준서에게 건넸어요.','작은 의자에 앉혔어요.'],'한 행동만 맞게 씀','주고받은 관계를 다시 바꿈')])

 E('plan-G2-language-10','S2','알려 주는 말과 묻는 말',
 '지우는 민서에게 내일 모임을 알려 주려고 쪽지를 썼어요.\n쪽지 가: 우리는 내일 운동장에 모여요.\n지우는 모이는 시간을 몰라 다시 물었어요.\n쪽지 나: 우리는 내일 몇 시에 모이나요?',
 '정보 전달과 시간 질문을 명시한 상황에서 문장 끝과 문장 부호를 살핀다. 물음표가 모든 의도를 결정한다는 규칙으로 일반화하지 않는다.',[
 A('explanation','모일 곳을 알려 주는 문장과 시간을 묻는 문장을 각각 써 보세요. 문장 끝도 함께 살피세요.','알려 주기:우리는 내일 운동장에 모여요. 묻기:우리는 내일 몇 시에 모이나요?',['쪽지 가: 우리는','쪽지 나: 우리는'],[D('말의 목적','장소 전달과 시간 질문을 각각 구별해 쓴다.','하나의 목적만 바르게 쓴다.','시간을 이미 알려 주었다고 한다.'),D('끝 표현','알려 주는 문장과 물어보는 문장의 끝을 뜻에 맞게 쓴다.','뜻은 맞으나 문장 끝 또는 부호 일부가 빠진다.','몇 시에 모이나요를 장소를 알려 주는 말로 바꾼다.')]),
 C('쪽지 나에 답하려면 어떤 정보를 주어야 하나요?','모이는 시간','몇 시인지 묻는 쪽지이므로 시간이 필요하다.',[('운동장이라는 장소','어디에 모이는지를 알려 주며 몇 시인지는 알려 주지 않는다.'),('내일이라는 날짜','어느 날인지는 알 수 있지만 그날 몇 시인지는 알 수 없다.')],'내일 몇 시에 모이나요?'),
 O('evidence_selection','지우가 시간을 모른다는 단서를 찾으세요.','모이는 시간을 몰라 다시 물었어요.','모이는 시간을 몰라','다시 물었다는 말만 씀','운동장에서 모인다는 문장을 고름'),
 O('explanation','민서가 아홉 시라고 답했어요. 모일 곳과 시간을 한 문장으로 알려 주세요.','우리는 내일 아홉 시에 운동장에 모여요.','내일 운동장에 모여요.','장소나 시간 하나만 포함함','장소를 교실로 바꿈')])
 E('plan-G2-language-10','S3','말에 이어지는 대답',
 '다희: “이 상자를 여기 놓을까요?”\n은우: “네, 탁자 위에 놓아 주세요.”\n다희는 상자를 탁자 위에 올려놓았어요.\n그다음 다희가 물었어요. “이 상자 안에는 무엇이 있나요?”\n은우: “색종이가 있어요.”',
 '놓을지 묻는 말의 대답과 내용물을 묻는 말의 대답을 잇는다. 문법적 종류의 용어 시험보다 대답의 관련성과 끝 표현을 확인한다.',[
 A('explanation','무엇이 있나요에 대한 은우의 대답을 쓰고, 놓을까요에 대한 대답과 어떻게 다른지 설명하세요.','색종이가 있어요는 내용물을 알려 준다. 네, 탁자 위에 놓아 주세요는 상자를 놓을 자리와 할 일을 알려 준다.',['탁자 위에 놓아 주세요.','색종이가 있어요.'],[D('대답 연결','내용물을 묻는 말에 색종이가 있다고 답한다.','색종이라고만 쓰고 질문과의 관계를 설명하지 못한다.','탁자 위에 놓으라는 말을 내용물의 답으로 삼는다.'),D('목적 비교','어디에 놓을지와 무엇이 있는지를 구별한다.','두 대답이 다르다고만 한다.','물음표가 같으므로 답도 같다고 한다.')]),
 C('다희가 실제로 상자를 놓은 곳은 어디인가요?','탁자 위','은우의 요청 뒤 탁자 위에 올려놓았다고 적혀 있다.',[('탁자 아래','글의 위치와 다르다.'),('상자 안','내용물이 있는 곳이며 상자를 놓은 곳은 아니다.')],'상자를 탁자 위에 올려놓았어요.'),
 O('matching','놓을까요 / 무엇이 있나요를 각각 알맞은 은우의 대답과 이으세요.','놓을까요:네, 탁자 위에 놓아 주세요. / 무엇이 있나요:색종이가 있어요.',['이 상자를 여기 놓을까요','이 상자 안에는 무엇이 있나요'],'한 쌍만 맞게 이음','대답을 서로 바꿈'),
 O('explanation','상자 안의 물건이 색연필로 바뀌었다면 마지막 대답을 어떻게 쓰면 될까요?','색연필이 있어요.','은우: “색종이가 있어요.”','색연필만 쓰고 대답 문장을 만들지 못함','놓아 달라는 말만 반복함')])
 E('plan-G2-language-10','S4','물음에 담긴 부탁',
 '소윤이는 양손으로 큰 종이를 들고 있었어요. 바람이 들어와 종이 끝이 자꾸 들렸어요.\n소윤이는 문 옆에 선 태오에게 “문을 닫아 줄래?”라고 물었어요.\n태오는 “응.” 하고 문을 닫았어요. 종이 끝이 더는 들리지 않았어요.',
 '질문의 형식을 이용해 행동을 부탁한 상황이다. 문법적 형식과 실제 전달 목적을 혼동하지 않는다. 음성 억양을 확인한 활동으로 표시하지 않는다.',[
 A('explanation','문을 닫아 줄래에 담긴 부탁을 더 분명한 문장으로 써 보세요. 왜 그런 부탁을 했는지도 설명하세요.','문을 닫아 줘. 또는 문을 닫아 주세요. 소윤이는 큰 종이를 양손에 들고 있었고 바람에 종이가 들려 태오에게 닫아 달라고 부탁했다.',['양손으로 큰 종이를','바람이 들어와 종이 끝이'],[D('뜻에 맞는 재표현','문을 닫아 달라는 부탁을 분명한 문장으로 쓴다.','문 닫기만 적고 부탁의 표현이 불분명하다.','문을 열어 달라고 바꾼다.'),D('상황 근거','종이·양손·바람 중 관련 단서를 연결해 이유를 설명한다.','부탁했다고만 한다.','태오가 추워했다고 없는 이유를 확정한다.')]),
 C('이 장면에서 소윤이가 태오에게 바란 일은 무엇인가요?','문을 닫는 일','태오에게 닫아 달라고 물었고 태오가 그 행동을 했다.',[('문을 닫는 방법을 알려 주는 일','방법을 설명해 달라는 말이 아니라 닫기 행동을 부탁한 상황이다.'),('문이 열렸는지 알려 주는 일','문 상태를 모르는 상황이 아니라 들어오는 바람을 막으려는 상황이다.')],'문을 닫아 줄래'),
 O('evidence_selection','태오가 부탁을 행동으로 받아들인 부분을 찾아 쓰세요.','태오는 “응.” 하고 문을 닫았어요.','하고 문을 닫았어요.','응이라는 대답만 쓰고 행동은 빠뜨림','종이 끝이 들렸다는 문장만 고름'),
 O('explanation','물음표가 있다고 언제나 정보만 묻는 말일까요? 이 장면으로 설명하세요.','이 장면에서는 문을 닫는 행동도 부탁한다. 물음표만 보고 정보만 묻는다고 정할 수 없다.','소윤이는 문 옆에 선 태오에게','아니라고만 하고 부탁을 밝히지 않음','물음표가 있으면 부탁일 수 없다고 함')])
 E('plan-G2-language-10','S5','같은 끝말, 다른 상황',
 '장면 가: 하나는 안쪽 방에 있어 창문이 보이지 않았어요. 하나가 거실의 아빠에게 “창문 열었어?”라고 묻자 아빠는 “아니, 아직 닫혀 있어.”라고 답했어요.\n장면 나: 하나는 창문 옆에 섰어요. 창문이 열린 것을 보고 아빠에게 “창문 열었어? 바람이 세니 닫아 줘.”라고 말했어요. 아빠는 창문을 닫았어요.',
 '같은 질문형도 두 장면에서 수행하는 역할을 비교한다. 나의 물음 자체만으로 간접 요청이라고 단정하지 않고 뒤의 명시적 부탁과 전체 발화를 함께 본다.',[
 A('explanation','하나가 장면 가와 나에서 하려는 말을 각각 더 분명하게 써 보세요. 왜 다르게 썼나요?','가:창문이 열려 있는지 알려 줘. 나:바람이 세니 열린 창문을 닫아 줘. 가는 보이지 않아 상태를 묻고 나는 열린 상태를 보고 닫아 달라고 부탁하기 때문이다.',['창문이 보이지 않았어요.','창문이 열린 것을 보고'],[D('두 목적 보존','가의 상태 확인과 나의 닫기 부탁을 각각 문장으로 쓴다.','한 장면만 목적에 맞게 쓴다.','두 장면 모두 창문을 열라는 말로 쓴다.'),D('문맥 비교','보이지 않는 상황과 열린 것을 본 뒤의 부탁을 근거로 구별한다.','끝말이 같거나 다르다고만 한다.','실제 목소리가 화났다고 없는 음성을 근거로 한다.')]),
 C('장면 나에서 닫아 달라는 뜻을 직접 드러낸 말은 무엇인가요?','바람이 세니 닫아 줘.','뒤의 문장이 닫기 행동을 명시적으로 부탁한다.',[('아니, 아직 닫혀 있어.','장면 가의 대답이다.'),('창문이 보이지 않았어요.','장면 가의 배경 설명이다.')],'바람이 세니 닫아 줘.'),
 O('explanation','창문 열었어 한마디만 따로 들으면 하나의 뜻을 모두 정할 수 있을까요?','앞뒤 상황이 없으면 상태만 묻는지 다른 뜻이 더 있는지 확정하기 어렵다.','장면 가: 하나는 안쪽 방에','모른다고만 함','언제나 닫으라는 뜻이라고 단정함'),
 O('evidence_selection','가에서 아빠가 상태를 알려 준 대답을 찾으세요.','아니, 아직 닫혀 있어.','아니, 아직 닫혀 있어.','아니만 적음','아빠가 창문을 닫았다는 나의 행동만 고름'),
 O('explanation','같은 끝말이면 언제나 같은 목적이라는 친구의 말을 두 장면으로 고쳐 보세요.','끝말이 같아도 상황과 뒤의 말에 따라 목적을 살펴야 한다. 가는 상태를 묻고 나는 닫기를 부탁한다.','아빠는 창문을 닫았어요.','다를 수 있다고만 함','같은 글자이므로 목적도 반드시 같다고 함')])
